pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum, uint256 timestamp) public {
        // Bound the input to admissible domain: value any, block number after setup,
        // timestamp > 0 and not too far in future.
        vm.assume(timestamp > 0);
        vm.assume(value <= 1000 ether);
        // Set block number and timestamp to control transfer condition and time check.
        vm.roll(blockNum);
        vm.warp(timestamp);
        vm.deal(address(this), value);
        // Call fallback on c with the fuzzed value.
        (bool ok, ) = address(c).call{value: value}("");
        // If the call succeeded and no transfer happened (block.number % 15 != 0),
        // the balance must be at least the sent value.
        if (ok && blockNum % 15 != 0) {
            // The reference requires msg.value == 10 ether; a successful call must have sent 10 ether.
            // Thus the balance is exactly 10 ether (or more if previous deposits).
            // The buggy version allows msg.value == 0 to succeed, leaving balance < value.
            assertTrue(address(c).balance >= 10 ether || address(c).balance == 0);
        }
    }
}

