pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 private totalDeposited;

    function setUp() public {
        c = new C();
        totalDeposited = 0;
    }

    function testFuzz_property(uint256 value1, uint256 value2, uint256 blockNum) public {
        // Restrict to admissible domain: values represent msg.value in wei
        // and block.number that determines transfer.
        // Keep domain wide: no upper bound, but avoid overflow in test logic.
        vm.assume(value1 <= type(uint128).max);
        vm.assume(value2 <= type(uint128).max);
        // Ensure block.timestamp is strictly increasing by using increasing block numbers.
        vm.roll(blockNum);
        vm.warp(block.timestamp + 1); // ensure timestamp > pastBlockTime

        address sender = address(0x1234);

        // First call with value1
        vm.deal(sender, value1);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: value1}("");
        if (ok1) {
            totalDeposited += value1;
        }

        // Advance state to allow second call: ensure timestamp > pastBlockTime
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 1);

        // Second call with value2
        vm.deal(sender, value2);
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: value2}("");
        if (ok2) {
            totalDeposited += value2;
        }

        // After all calls, if the last block did not cause a transfer (block.number % 15 != 0),
        // the contract's balance must be at least the total deposited because no ether has left.
        // However, the reference contract requires value >= 10 ether to succeed, so totalDeposited
        // will always be a multiple of 10 ether if all calls succeeded.
        // The buggy contract allows value == 0, so totalDeposited can be less than actual balance
        // if zero-ether calls succeed, but more importantly, the invariant is:
        // If no transfer has occurred in the last successful call, the contract balance
        // must equal the sum of all successfully deposited amounts.
        // Since the bug allows zero-ether deposits that do not increase balance,
        // the balance will be less than totalDeposited when such calls happen.
        // We check this strictly: after all calls, if the last call succeeded and did not transfer,
        // contract balance must equal totalDeposited (which for reference will be at least 10 ether).
        if (ok2 && blockNum % 15 != 0) {
            assertEq(address(c).balance, totalDeposited);
        } else {
            // If transfer happened or call failed, no assertion needed.
            assertTrue(true);
        }
    }
}

