pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint32 timeIncrease1, uint32 timeIncrease2, uint88 value, uint64 blockNumber) public {
        uint256 v = uint256(value) * 1e10;
        uint256 val = v < 10 ether ? v + 10 ether : v;
        vm.assume(val >= 10 ether);
        vm.assume(timeIncrease1 > 0);
        vm.assume(timeIncrease2 > 0);
        vm.assume(blockNumber > 0);
        uint256 currentBlock = block.number + 1;
        vm.roll(currentBlock);
        uint256 startTime = block.timestamp + 1 hours;
        vm.warp(startTime);

        address sender = address(0x1234);
        vm.deal(sender, 20 ether);

        // First call: must succeed, block.number mod 15 == 0 check irrelevant, we choose a block number that does NOT
        // trigger the transfer (avoid early drain).
        uint256 b1 = currentBlock + uint256(blockNumber);
        if (b1 % 15 == 0) {
            b1 += 1;
        }
        vm.roll(b1);
        uint256 t1 = startTime + uint256(timeIncrease1);
        vm.warp(t1);
        vm.prank(sender);
        c.fallback{value: val}();

        // Second call: must use a higher timestamp and not trigger a transfer.
        uint256 b2 = b1 + 1 + uint256(blockNumber);
        if (b2 % 15 == 0) {
            b2 += 1;
        }
        vm.roll(b2);
        uint256 t2 = t1 + uint256(timeIncrease2);
        vm.warp(t2);
        vm.prank(sender);
        // In the reference version, pastBlockTime is updated to t1, so t2 > t1 holds.
        // In the mutant, pastBlockTime remains 0 (or the initial zero), so t2 > 0, which is true, BUT the difference
        // manifests as a revert if we check that pastBlockTime has actually been set to t1.
        // Instead we check the actual observable state: after the second call, pastBlockTime should equal t1.
        // The mutant will have pastBlockTime still at 0 (or the value from initialization).
        // However, the second call itself succeeds in both versions under our careful setup (t2 > 0 and no transfer).
        // The real divergence is that pastBlockTime is not updated in the mutant.
        // So we assert that after the two calls, pastBlockTime reflects the timestamp of the first call.
        c.fallback{value: val}();

        // Property: pastBlockTime must be the timestamp of the last *valid* fallback call, which is t1.
        // The mutant fails to update pastBlockTime, so it remains 0, breaking this property.
        assertTrue(c.pastBlockTime() == t1);
    }
}

