        // Second fallback call: block.timestamp = 1000 + delay
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: val}("");
        require(ok2, "second call failed");

        // Property: pastBlockTime must equal the timestamp of the last successful call
        assertEq(c.pastBlockTime(), 1000 + delay);
