pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 numCalls, uint256 warpSeed) public {
        // Make at least one call so balance changes, keep it bounded to avoid timeout
        uint256 n = bound(numCalls, 1, 20);
        address actor = makeAddr("actor");
        vm.deal(actor, 10 ether * n);
        vm.startPrank(actor);
        uint256 balanceBefore = address(c).balance;
        for (uint256 i = 0; i < n; i++) {
            // Warp to a future time to satisfy the timestamp requirement
            vm.warp(block.timestamp + 1 + (warpSeed % 1000) + i);
            // Ensure block.number changes so at least some calls hit the transfer condition
            vm.roll(block.number + 1 + i);
            (bool ok,) = address(c).call{value: 10 ether}("");
            require(ok, "fallback call failed");
        }
        // The invariant: after any number of successful fallback calls, the contract's
        // balance is at most what it was before the first call (non-increasing).
        // Reference: transfers entire balance on block.number%15==0 -> balance decreases to 0.
        // Buggy: never transfers -> balance strictly increases with each call.
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter <= balanceBefore);
    }
}

