        (bool ok1, ) = address(c).call{value: value}("");
        require(ok1, "first call failed");
        uint256 firstPastBlockTime = c.pastBlockTime();

        // Second call at the exact same timestamp (no time advancement)
        // This triggers the bug: pastBlockTime is set to block.timestamp before the require,
        // making block.timestamp > pastBlockTime false, causing revert
        vm.deal(address(this), value);
        (bool ok2, ) = address(c).call{value: value}("");

        // In the reference contract, the second call succeeds and pastBlockTime == block.timestamp.
        // In the buggy contract, the second call reverts, leaving pastBlockTime unchanged.
        if (ok2) {
            assertEq(c.pastBlockTime(), block.timestamp, "pastBlockTime must equal current timestamp after success");
        } else {
            assertEq(c.pastBlockTime(), firstPastBlockTime, "pastBlockTime unchanged on revert");
        }
    }
}
